// Agent Workflow extension for Pi (generated by agent-workflow sync; do not edit).
// Once per session, before the first agent run, adds the project-gated reminder as a hidden
// message. No commands, network, project code or transcript access; opted-out projects get nothing.
import {hookResult} from '__AW_GATE_URL__';

export default function agentWorkflow(pi){
  let sent=false;
  pi.on('session_start',async()=>{sent=false;});
  pi.on('before_agent_start',async(event,ctx)=>{
    if(sent)return;
    sent=true;
    let text;
    try{text=hookResult({cwd:ctx?.cwd??event?.systemPromptOptions?.cwd??process.cwd(),hook_event_name:'SessionStart'}).hookSpecificOutput?.additionalContext;}catch{return;}
    if(!text)return;
    return {message:{customType:'agent-workflow',content:text,display:false}};
  });
}
